import{_ as a,o as t,c as l,a2 as o}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Payroll Cycle Budget","description":"","frontmatter":{"title":"Payroll Cycle Budget"},"headers":[],"relativePath":"operations/payroll-cycle-budget.md","filePath":"operations/payroll-cycle-budget.md","lastUpdated":1787839527000}'),r={name:"operations/payroll-cycle-budget.md"};function i(s,e,n,d,c,p){return t(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="發薪週期預算" tabindex="-1">發薪週期預算 <a class="header-anchor" href="#發薪週期預算" aria-label="Permalink to &quot;發薪週期預算&quot;">​</a></h1><h2 id="語意" tabindex="-1">語意 <a class="header-anchor" href="#語意" aria-label="Permalink to &quot;語意&quot;">​</a></h2><p>帳本層設定，<strong>不是</strong>每個預算項目自己的發薪日。</p><ul><li>模式：<code>calendar_month</code> 或 <code>pay_cycle</code></li><li><code>pay_cycle</code>：從發薪日（含）到下次發薪日前一日（含）</li><li>發薪日當天 <code>00:00</code>（帳本時區）起屬新期；前一日仍屬舊期</li><li>日均／日池依<strong>實際週期天數</strong>，不能只讓固定額套用週期</li><li>日曆／交易／分析預設仍是曆月；預算頁與首頁預算卡跟週期走</li></ul><p>month key 形如 <code>pay:YYYY-MM-DD</code>。</p><h2 id="使用者入口-必須找得到" tabindex="-1">使用者入口（必須找得到） <a class="header-anchor" href="#使用者入口-必須找得到" aria-label="Permalink to &quot;使用者入口（必須找得到）&quot;">​</a></h2><ol><li><strong>預算頁本體</strong>（<code>/budget</code>）：曆月／發薪週期切換 + 發薪日</li><li>新增／編輯預算項目 sheet、共同池 sheet</li><li>設定 → 帳本詳情（深度連結）</li></ol><p>PostSetup／文案不可再寫「從設定啟用進階功能」當主入口。</p><h2 id="驗收" tabindex="-1">驗收 <a class="header-anchor" href="#驗收" aria-label="Permalink to &quot;驗收&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright:budget-pay-cycle</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend</span></span></code></pre></div><p>必覆蓋：跨月、跨年、短月 29/30/31、歷史月相容、同週期重複結算防護、從預算頁（含 app shell）操作。</p><p>自動 rollover：首次開啟、reload、App 從背景跨日回前景都要依<strong>當天</strong>重算；不可只靠「上一期／下一期」按鈕。</p><h2 id="引用" tabindex="-1">引用 <a class="header-anchor" href="#引用" aria-label="Permalink to &quot;引用&quot;">​</a></h2><ul><li><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/frontend/src/core/services/budget-period.js" target="_blank" rel="noreferrer"><code>frontend/src/core/services/budget-period.js</code></a></li><li><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/frontend/src/core/db/migrations/039_budget_pay_cycle.sql" target="_blank" rel="noreferrer"><code>frontend/src/core/db/migrations/039_budget_pay_cycle.sql</code></a></li><li><a href="/operations/playwright-app-shell.html">Playwright-App-Shell</a></li></ul>',14)])])}const u=a(r,[["render",i]]);export{g as __pageData,u as default};
